use serde_json::{json,Value};use sha2::{Sha256,Digest};use std::{fs,path::Path,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/wire-union-census175";const F:&str="/home/ubuntu/src/zopro-perf-work/balanced-kh-production/frozen-candidate.json";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let root=Path::new(R);assert!(!root.join("plan.json").exists());let frozen=read(F);let manifest=read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json");let mut pins=BTreeMap::<String,String>::new();for(p,h)in frozen["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.clone(),h.as_str().unwrap().into());}for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){let path=Path::new("/home/ubuntu/src/zk-tools/zopro").join(p);assert_eq!(hash(&path),h.as_str().unwrap());pins.insert(path.display().to_string(),h.as_str().unwrap().into());}
let builder="/home/ubuntu/src/zopro-perf-work/index-groups175/builders.rs";let text=fs::read_to_string(builder).unwrap();let legacy=text.split_once("\npub fn candidate").unwrap().0;fs::write(root.join("legacy.rs"),legacy).unwrap();pins.insert(builder.into(),hash(builder));let cases="/home/ubuntu/src/zopro-perf-work/swiss-groups175/cases.json";fs::copy(cases,root.join("cases.json")).unwrap();for c in read(cases).as_array().unwrap().iter().take(9){for key in["key","request"]{let p=c[key].as_str().unwrap();pins.insert(p.into(),hash(p));}}
let dir=Path::new(frozen["libraries"]["zopro_core"].as_str().unwrap()).parent().unwrap();let ahash=fs::read_dir(dir).unwrap().map(|e|e.unwrap().path()).find(|p|p.file_name().unwrap().to_str().unwrap().starts_with("libahash-")&&p.extension().unwrap()=="rlib").unwrap();let mut args=vec!["rustc".to_string(),"--edition=2021".into(),"-O".into(),"-C".into(),"target-cpu=native".into(),"-C".into(),"lto=fat".into(),"-C".into(),"codegen-units=1".into(),"-L".into(),format!("dependency={}",dir.display())];for(n,p)in frozen["libraries"].as_object().unwrap(){args.extend(["--extern".into(),format!("{n}={}",p.as_str().unwrap())]);}args.extend(["--extern".into(),format!("ahash={}",ahash.display()),root.join("probe.rs").display().to_string()]);let mut tests=args.clone();tests.extend(["--test".into(),"-o".into(),root.join("tests").display().to_string()]);let mut probe=args;probe.extend(["-o".into(),root.join("probe").display().to_string()]);for p in["setup.rs","setup","probe.rs","legacy.rs","design.md","cases.json"]{let p=root.join(p);pins.insert(p.display().to_string(),hash(&p));}pins.insert(F.into(),hash(F));let save=|name:&str,v:&Value|fs::write(root.join(name),serde_json::to_vec_pretty(v).unwrap()).unwrap();save("pins.json",&json!(pins));save("plan.json",&json!({"version":1,"source_pins":root.join("pins.json"),"steps":[{"kind":"command","name":"compile-tests","argv":tests,"timeout_seconds":900},{"kind":"command","name":"test-model","argv":[root.join("tests"),"--test-threads=1"],"unfiltered":true,"timeout_seconds":300},{"kind":"command","name":"compile-probe","argv":probe,"timeout_seconds":900},{"kind":"command","name":"count-real-queries","argv":[root.join("probe"),root.join("cases.json")],"environment":manifest["environment"],"timeout_seconds":1800}]}));println!("Prepared wire-union scalar/metadata screen, 4steps/{}pins, no latency/proof capture",pins.len());}
